using Cogpunk.Core.Templates;
using Microsoft.Xna.Framework;
using Terraria;
using Terraria.ID;
using Terraria.ModLoader;

namespace Cogpunk.Content.Coghaven.Tiles
{
	/// <summary>
	/// Palace Flagstone (2026-11-06, the user's second request that day: "Coghaven's floor should not be made from jade
	/// brick, only the roof"): pale stone pavers with a bronze stud where the joints cross, every floor, terrace, plinth
	/// and stair of Coghaven's palace (the jade is the roofs' alone). Generated by <see cref="Generation.CoghavenPass"/>;
	/// seamless clump art from art/coghaven/make_coghaven_art.py.
	/// </summary>
	public class PalaceFlagstoneTile : CogpunkTile
	{
		public override void SetStaticDefaults() {
			TileID.Sets.GeneralPlacementTiles[Type] = false;   // later world-gen features (other mods) keep off the palace
			Main.tileSolid[Type] = true;
			Main.tileBlockLight[Type] = true;
			DustType = DustID.Stone;
			HitSound = SoundID.Tink;
			AddMapEntry(new Color(196, 180, 150), CreateMapEntryName());
			RegisterItemDrop(ModContent.ItemType<Items.PalaceFlagstone>());
		}
	}
}
